153: export function simpleCompactMessages(messages: Message[], keepRecent: number): Message[] {
154:   const systemMessages = messages.filter((m) => m.type === "system");
155:   const nonSystem = messages.filter((m) => m.type !== "system");
156: 
157:   const { older, recent } = splitMessagesPreservingToolPairs(nonSystem, keepRecent);
158:   if (older.length === 0) return messages;
159: 
160:   const compactedCount = older.length;
161:   const toolResultCount = older.filter((m) => m.type === "tool_result").length;
162:   const retainedFacts: string[] = [];
163:   const pairedIds = new Set(older.flatMap((message) => message.type === "assistant" ? (message.toolUses ?? []).map((call) => call.id) : []));
164:   let remaining = 900; // Reserve the omission marker and empty continuity seal within 1,000 characters.
165:   let omitted = false;
166:   for (const message of older.slice().reverse()) {
167:     if (message.type !== "tool_result") continue;
168:     // Matched observations are carried once by the bounded source capsule below.
169:     if (pairedIds.has(message.toolUseId)) continue;
170:     const facts = toolFactsText(message);
171:     if (!facts) continue;
172:     if (facts.length + 1 > remaining) {
173:       omitted = true;
174:       continue;
175:     }
176:     retainedFacts.unshift(facts);
177:     remaining -= facts.length + 1;
178:   }
179:   if (omitted) retainedFacts.push("[Some tool observations omitted]");
180: 
181:   const summary: Message = {
182:     type: "assistant",
183:     content: appendContinuityExcerpts([`[Conversation compacted: ${compactedCount} messages summarized (${toolResultCount} tool results removed). ${recent.length} recent messages preserved.]`, ...retainedFacts].join("\n"), older),
184:     compactRole: "summary",
185:   };
186: 
187:   const boundary = createCompactBoundaryMarker({
188:     trigger: "auto",
189:     compactKind: "simple",
190:     preMessageCount: messages.length,
191:     postMessageCount: systemMessages.length + 1 + recent.length,
192:   });
193: 
194:   return [...systemMessages, summary, boundary, ...recent];
195: }
