197: export function tryContextCollapseMessages(messages: Message[], keepRecent: number, imageTokenEstimate: number): Message[] | null {
198:   // 消息太少时没有「较旧」可压，直接跳过。
199:   if (messages.length <= keepRecent + 2) return null;
200: 
201:   const { older, recent } = splitMessagesPreservingToolPairs(messages, keepRecent);
202:   let changed = false;
203: 
204:   const collapsedOlder = older.map((msg) => {
205:     // user：content 可能是 ContentBlock[]（含 text / image）
206:     if (msg.type === "user" && Array.isArray(msg.content)) {
207:       const blocks = msg.content.map((b) => {
208:         if (isTextBlock(b)) {
209:           const collapsed = collapseText(b.text);
210:           if (collapsed !== b.text) changed = true;
211:           return { type: "text" as const, text: collapsed };
212:         }
213:         return b;
214:       });
215:       return { ...msg, content: blocks } as Message;
216:     }
217:     // user：纯字符串 content
218:     if (msg.type === "user" && typeof msg.content === "string") {
219:       const collapsed = collapseText(msg.content);
220:       if (collapsed !== msg.content) changed = true;
221:       return { ...msg, content: collapsed } as Message;
222:     }
223:     // assistant：content 为字符串
224:     if (msg.type === "assistant") {
225:       const owned = splitOwnedContinuity(msg);
226:       const collapsed = owned ? `${collapseText(owned.text)}\n${owned.container}` : collapseText(msg.content);
227:       if (collapsed !== msg.content) changed = true;
228:       return { ...msg, content: collapsed } as Message;
229:     }
230:     // tool_result：content 为 block 数组
231:     if (msg.type === "tool_result") {
232:       let bodyChanged = false;
233:       const blocks = msg.content.map((b) => {
234:         if (isTextBlock(b)) {
235:           const collapsed = collapseText(b.text);
236:           if (collapsed !== b.text) changed = bodyChanged = true;
237:           return { type: "text" as const, text: collapsed };
238:         }
239:         return b;
240:       });
241:       return { ...msg, content: bodyChanged ? prependToolFacts(blocks, toolFactsText(msg)) : blocks } as Message;
242:     }
243:     return msg;
244:   });
245: 
246:   if (!changed) return null;
247: 
248:   const result = [...collapsedOlder, ...recent];
249:   // 若估算未下降（例如 padding / 图片主导），视为无效，返回 null。
250:   if (estimateMessageTokens(result, imageTokenEstimate) >= estimateMessageTokens(messages, imageTokenEstimate)) {
251:     return null;
252:   }
253:   return result;
254: }
