256: function collapseText(text: string): string {
257:   if (text.length <= CONTEXT_COLLAPSE_TEXT_CHAR_LIMIT) return text;
258:   const omitted =
259:     text.length - CONTEXT_COLLAPSE_HEAD_CHARS - CONTEXT_COLLAPSE_TAIL_CHARS;
260:   const head = text.slice(0, CONTEXT_COLLAPSE_HEAD_CHARS).trimEnd();
261:   const tail = text.slice(-CONTEXT_COLLAPSE_TAIL_CHARS).trimStart();
262:   return `${head}\n...[collapsed ${omitted} chars]...\n${tail}`;
263: }
