265: export function truncateHeadForPtlRetry(messages: Message[]): Message[] | null {
266:   const groups = groupByPromptRound(messages);
267:   if (groups.length < 2) return null;
268: 
269:   let dropCount = Math.max(1, Math.floor(groups.length / 5));
270:   dropCount = Math.min(dropCount, groups.length - 1);
271: 
272:   const retained = groups.slice(dropCount).flat();
273:   if (!retained.length) return null;
274: 
275:   if (retained[0]!.type === "assistant" || retained[0]!.type === "tool_result") {
276:     const marker: Message = { type: "user", content: PTL_RETRY_MARKER };
277:     return [marker, ...retained];
278:   }
279:   return retained;
280: }
