282: function groupByPromptRound(messages: Message[]): Message[][] {
283:   const groups: Message[][] = [];
284:   let current: Message[] = [];
285:   for (const msg of messages) {
286:     const startsNewRound =
287:       msg.type === "user" && contentToText(msg.content).trim().length > 0;
288:     if (startsNewRound && current.length) {
289:       groups.push(current);
290:       current = [];
291:     }
292:     current.push(msg);
293:   }
294:   if (current.length) groups.push(current);
295:   return groups;
